bool Boarding_CabinLootReady()
{
	if (!LAi_boarding_process || boarding_location_type != BRDLT_SHIP) return false;
	if (!CheckAttribute(&boarding_loot, "location")) return false;
	if (sti(boarding_loot.location) != boarding_location || boarding_location < 0) return false;
	if (pchar.location != Locations[boarding_location].id) return false;
	if (!IsEntity(&Locations[boarding_location])) return false;
	if (!CheckAttribute(&Locations[boarding_location], "CabinType")) return false;
	if (sti(boarding_loot.enemy) != sti(boarding_enemy.index)) return false;
	return boarding_loot.enemyId == boarding_enemy.id;
}

bool Boarding_IsProtectedLoot(string itemID)
{
	aref item;
	if (Items_FindItem(itemID, &item) < 0) return true;
	if (CheckAttribute(item, "quest") || CheckAttribute(item, "unique")) return true;
	if (CheckAttribute(item, "gold") || IsQuestUsedItem(itemID)) return true;
	if (CheckAttribute(item, "ItemType"))
	{
		if (item.ItemType == "QUESTITEMS" || item.ItemType == "MAP" || item.ItemType == "BOOK") return true;
	}
	// Missing rarity is unknown, not permission to sweep a unique reward.
	if (!CheckAttribute(item, "rare")) return true;
	return stf(item.rare) < 0.01;
}

bool Boarding_HasProtectedCabinLoot()
{
	if (!Boarding_CabinLootReady()) return true;
	aref boxLocator, items;
	ref cabin = &Locations[boarding_location];
	for (int box = 1; box < MAX_HANDLED_BOXES; box++)
	{
		string name = "box" + box;
		// Match Box_OnLoadLocation: stale attributes without a locator are not loot.
		if (!FindLocator(cabin.id, name, &boxLocator, true)) break;
		if (!CheckAttribute(cabin, name + ".items")) continue;
		makearef(items, cabin.(name).items);
		for (int i = 0; i < GetAttributesNum(items); i++)
		{
			aref entry = GetAttributeN(items, i);
			if (sti(GetAttributeValue(entry)) <= 0) continue;
			if (Boarding_IsProtectedLoot(GetAttributeName(entry))) return true;
		}
	}
	return false;
}

int Boarding_TransferCabinLoot()
{
	if (!Boarding_CabinLootReady() || !CheckAttribute(&boarding_loot, "cleared")) return 0;
	int destination = FindLocation(Get_My_Cabin());
	if (destination < 0 || destination == boarding_location) return 0;
	ref cabin = &Locations[boarding_location];
	ref chest = &Locations[destination];
	aref boxLocator, source, items;
	int transferred = 0;
	for (int box = 1; box < MAX_HANDLED_BOXES; box++)
	{
		string name = "box" + box;
		if (!FindLocator(cabin.id, name, &boxLocator, true)) break;
		if (!CheckAttribute(cabin, name)) continue;
		makearef(source, cabin.(name));
		if (CheckAttribute(source, "money") && sti(source.money) > 0)
		{
			int money = sti(source.money);
			AddMoneyToCharacter(pchar, money);
			source.money = 0;
			transferred += money;
		}
		if (!CheckAttribute(source, "items")) continue;
		makearef(items, source.items);
		for (int i = GetAttributesNum(items) - 1; i >= 0; i--)
		{
			aref entry = GetAttributeN(items, i);
			string itemID = GetAttributeName(entry);
			int quantity = sti(GetAttributeValue(entry));
			if (quantity <= 0 || Boarding_IsProtectedLoot(itemID)) continue;
			aref destinationBox;
			makearef(destinationBox, chest.box1);
			int previous = GetCharacterItem(destinationBox, itemID);
			if (!TakeNItems(destinationBox, itemID, quantity)) continue;
			if (GetCharacterItem(destinationBox, itemID) != previous + quantity) continue;
			if (!TakeNItems(source, itemID, -quantity))
			{
				TakeNItems(destinationBox, itemID, -quantity);
				continue;
			}
			transferred += quantity;
		}
	}
	return transferred;
}

// A location phantom delivers the order even when no officer joined boarding.
#event_handler("Boarding_CabinLootDialog", "Boarding_ShowCabinLootDialog");
void Boarding_ShowCabinLootDialog()
{
	if (!Boarding_CabinLootReady() || !CheckAttribute(&boarding_loot, "cleared")) return;
	if (CheckAttribute(&boarding_loot, "done")) return;
	ref mate;
	if (CheckAttribute(&boarding_loot, "speaker"))
	{
		mate = &Characters[sti(boarding_loot.speaker)];
		if (!IsEntity(mate) || LAi_IsDead(mate)) DeleteAttribute(&boarding_loot, "speaker");
	}
	if (!CheckAttribute(&boarding_loot, "speaker"))
	{
		string animation;
		string model = LAi_GetBoardingModel(pchar, &animation);
		mate = LAi_CreateFantomCharacterEx(model, animation, "rld", Locations[boarding_location].boarding.Loc.Capt);
		if (!IsEntity(mate))
		{
			Boarding_FinishCabinLoot();
			return;
		}
		mate.AboardFantom = true;
		mate.BoardingLootMate = true;
		LAi_group_MoveCharacter(mate, LAI_GROUP_PLAYER);
		boarding_loot.speaker = mate.index;
	}
	// ChrAction also opens boxes: release the boarding reload hook while inspecting.
	DelEventHandler("Control Activation", "LAi_ActivateReload");
	mate.Dialog.Filename = "Enc_Officer_dialog.c";
	mate.Dialog.CurrentNode = "BoardingLoot";
	mate.Dialog.TempNode = "BoardingLoot";
	dialogDisable = false;
	SendMessage(&pchar, "lsl", MSG_CHARACTER_EX_MSG, "ChangeFightMode", 0);
	LAi_SetActorType(mate);
	LAi_ActorDialogNow(mate, pchar, "", -1);
}

void Boarding_InspectCabinLoot()
{
	if (!Boarding_CabinLootReady() || !CheckAttribute(&boarding_loot, "speaker")) return;
	ref mate = &Characters[sti(boarding_loot.speaker)];
	if (IsEntity(mate)) LAi_SetStayType(mate);
}

bool Boarding_PreserveCabinLoot()
{
	if (!Boarding_CabinLootReady() || !CheckAttribute(&boarding_loot, "cleared")) return false;
	int destination = FindLocation(Get_My_Cabin());
	if (destination < 0 || destination == boarding_location) return false;
	ref cabin = &Locations[boarding_location];
	aref destinationBox, boxLocator, source, items, item;
	makearef(destinationBox, Locations[destination].box1);
	for (int box = 1; box < MAX_HANDLED_BOXES; box++)
	{
		string name = "box" + box;
		if (!FindLocator(cabin.id, name, &boxLocator, true)) break;
		if (!CheckAttribute(cabin, name + ".items")) continue;
		makearef(source, cabin.(name));
		makearef(items, source.items);
		for (int i = GetAttributesNum(items) - 1; i >= 0; i--)
		{
			aref entry = GetAttributeN(items, i);
			string itemID = GetAttributeName(entry);
			int quantity = sti(GetAttributeValue(entry));
			if (quantity <= 0 || !Boarding_IsProtectedLoot(itemID)) continue;
			bool saved = false;
			if (Items_FindItem(itemID, &item) >= 0)
			{
				// Keep normal inventory/quest notifications, including gold conversion.
				int previous = GetCharacterItem(pchar, itemID);
				int previousMoney = sti(pchar.money);
				if (TakeNItems(pchar, itemID, quantity))
				{
					if (CheckAttribute(item, "gold"))
					{
						saved = sti(pchar.money) == previousMoney + quantity * sti(item.gold);
					}
					else
					{
						saved = GetCharacterItem(pchar, itemID) == previous + quantity;
					}
				}
				if (!saved)
				{
					// Full inventory or duplicate unique suppression: retain it in the chest.
					if (GetCharacterItem(pchar, itemID) != previous || sti(pchar.money) != previousMoney) return false;
					previous = GetCharacterItem(destinationBox, itemID);
					if (TakeNItems(destinationBox, itemID, quantity))
						saved = GetCharacterItem(destinationBox, itemID) == previous + quantity;
					if (!saved)
					{
						if (GetCharacterItem(destinationBox, itemID) != previous) return false;
						// Storage must retain suppressed duplicates and overflow, not grant them.
						int retained = previous + quantity;
						if (retained <= previous) return false;
						destinationBox.items.(itemID) = retained;
						saved = GetCharacterItem(destinationBox, itemID) == retained;
					}
				}
			}
			else
			{
				// Unknown IDs cannot use TakeNItems; preserve the exact ID and count.
				int stored = GetCharacterItem(destinationBox, itemID);
				int total = stored + quantity;
				if (total <= stored) return false;
				destinationBox.items.(itemID) = total;
				saved = GetCharacterItem(destinationBox, itemID) == total;
			}
			if (!saved) return false;
			// Never remove a source entry before its destination quantity is verified.
			DeleteAttribute(source, "items." + itemID);
		}
	}
	CheckAndSetOverloadMode(pchar);
	RefreshEquippedMaps(pchar);
	return !Boarding_HasProtectedCabinLoot();
}

void Boarding_FinishCabinLoot()
{
	if (!Boarding_CabinLootReady() || !CheckAttribute(&boarding_loot, "cleared")) return;
	if (!Boarding_PreserveCabinLoot()) return;
	boarding_loot.done = true;
	DelEventHandler("Control Activation", "LAi_ActivateReload");
	Log_SetActiveAction("Nothing");
	LAi_ReloadBoarding();
}

bool Boarding_StartSurrenderCabin(ref enemy)
{
	if (boarding_location_type != BRDLT_SHIP || GetCharacterShipClass(enemy) == 7) return false;
	string cabinID = GetShipCabinID(enemy);
	int cabin = FindLocation(cabinID);
	if (cabin < 0) return false;
	if (!CheckAttribute(&Locations[cabin], "CabinType")) return false;
	boarding_enemy = enemy;
	boarding_adr[0].location = pchar.location;
	boarding_adr[0].group = pchar.location.group;
	boarding_adr[0].locator = pchar.location.locator;
	boarding_loot.immediate = true;
	boarding_loot.peaceful = true;
	LAi_boarding_process = true;
	LAi_LoadLocation(cabinID, BRDLT_SHIP);
	if (Boarding_CabinLootReady())
	{
		CreateEntity(&boarding_fader, "fader");
		SendMessage(&boarding_fader, "lfl", FADER_IN, RELOAD_TIME_FADE_IN, true);
		return true;
	}
	// Loading failure retains the original capture path and player address.
	pchar.location = boarding_adr[0].location;
	pchar.location.group = boarding_adr[0].group;
	pchar.location.locator = boarding_adr[0].locator;
	boarding_location = -1;
	LAi_boarding_process = false;
	DeleteAttribute(&boarding_loot, "");
	return false;
}

