// Only a present, available storekeeper can buy the captain's cabin stock.
int Treasurer_JunkBuyer()
{
    if (bSeaActive || LAi_grp_alarmactive || LAi_grp_playeralarm > 0) return -1;
    if (LAi_IsFightMode(pchar)) return -1;
    if (CheckAttribute(pchar, "questTemp.CapBloodLine") && sti(pchar.questTemp.CapBloodLine)) return -1;
    ref trader;
    for (int index = 0; index < TOTAL_CHARACTERS; index++)
    {
        trader = GetCharacter(index);
        if (!CheckAttribute(trader, "Dialog.Filename")) continue;
        if (trader.Dialog.Filename != "Common_Store.c") continue;
        if (!CheckAttribute(trader, "location")) continue;
        if (trader.location != pchar.location) continue;
        if (!IsEntity(trader) || LAi_IsDead(trader)) continue;
        if (!CheckAttribute(trader, "City")) continue;
        if (CheckFreeServiceForNPC(trader, "Store") != -1) continue;
        if (CheckAttribute(trader, "angry")) continue;
        if (!CheckAttribute(trader, "Dialog.CurrentNode")) continue;
        string node = trader.Dialog.CurrentNode;
        if (node != "First time" && node != "Second time" && node != "market") continue;
        return index;
    }
    return -1;
}

bool Treasurer_ItemNeededBy(ref officer, ref item)
{
    string equipped = GetCharacterEquipByGroup(officer, item.groupID);
    if (equipped == item.id) return true;
    if (OfficerSupply_IsEquipmentLocked(officer, item.groupID, equipped)) return false;
    float candidateScore = OfficerSupply_ItemScore(officer, item, item.groupID);
    if (candidateScore < 0.0) return false;
    if (equipped == "" || equipped == "unarmed") return true;
    aref current;
    if (Items_FindItem(equipped, &current) < 0) return true;
    return candidateScore > OfficerSupply_ItemScore(officer, current, item.groupID);
}

bool Treasurer_ItemNeeded(ref item)
{
    if (Treasurer_ItemNeededBy(pchar, item)) return true;
    int index;
    ref officer;
    for (int slot = 0; slot < GetPassengersQuantity(pchar); slot++)
    {
        index = GetPassenger(pchar, slot);
        if (index < 0) continue;
        officer = GetCharacter(index);
        if (!GetRemovable(officer)) continue;
        if (CheckAttribute(officer, "prisoned") && sti(officer.prisoned)) continue;
        if (Treasurer_ItemNeededBy(officer, item)) return true;
    }
    for (int ship = 1; ship < COMPANION_MAX; ship++)
    {
        index = GetCompanionIndex(pchar, ship);
        if (index < 0) continue;
        officer = GetCharacter(index);
        if (!FleetService_IsShip(officer)) continue;
        if (Treasurer_ItemNeededBy(officer, item)) return true;
    }
    return false;
}

int Treasurer_SellJunkFromChest()
{
    int buyerIndex = Treasurer_JunkBuyer();
    if (buyerIndex < 0) return 0;
    int cabinIndex = FindLocation(Get_My_Cabin());
    if (cabinIndex < 0) return 0;
    if (!CheckAttribute(&Locations[cabinIndex], "box1.items")) return 0;
    ref buyer = GetCharacter(buyerIndex);
    aref chest, chestItems;
    makearef(chest, Locations[cabinIndex].box1);
    makearef(chestItems, Locations[cabinIndex].box1.items);
    int proceeds = 0;
    ref item;
    // Same PRICE_TYPE_SELL modifier as interface/itemstrade.c; its function is
    // interface-segment-local and cannot be loaded over an officer dialogue.
    float modifier = 0.75 + GetSummonSkillFromNameToOld(pchar, SKILL_COMMERCE) * 0.019;
    if (CheckOfficersPerk(pchar, "AdvancedCommerce")) modifier += 0.05;
    for (int index = GetAttributesNum(chestItems) - 1; index >= 0; index--)
    {
        aref entry = GetAttributeN(chestItems, index);
        string itemID = GetAttributeName(entry);
        int quantity = sti(GetAttributeValue(entry));
        if (quantity < 1) continue;
        aref found;
        int itemIndex = Items_FindItem(itemID, &found);
        if (itemIndex < 0) continue;
        item = &Items[itemIndex];
        if (!CheckAttribute(item, "groupID")) continue;
        if (item.groupID != BLADE_ITEM_TYPE && item.groupID != GUN_ITEM_TYPE && item.groupID != CIRASS_ITEM_TYPE) continue;
        if (itemID == "unarmed" || itemID == "CaptainBook") continue;
        if (CheckAttribute(item, "quest") || CheckAttribute(item, "unique")) continue;
        if (CheckAttribute(item, "ItemType"))
        {
            if (item.ItemType == "QUESTITEMS" || item.ItemType == "MAP" || item.ItemType == "BOOK") continue;
        }
        if (!CheckAttribute(item, "price")) continue;
        int price = sti(item.price);
        if (price <= 0 || price >= 1500) continue;
        // Missing rarity is unknown, not permission to sell a unique reward.
        if (!CheckAttribute(item, "rare")) continue;
        if (stf(item.rare) < 0.01) continue;
        if (IsQuestUsedItem(itemID) || Treasurer_ItemNeeded(item)) continue;
        int salePrice = makeint(price * modifier);
        if (salePrice < 1) continue;
        int buyerQuantity = GetCharacterItem(buyer, itemID);
        if (!TakeNItems(buyer, itemID, quantity)) continue;
        if (GetCharacterItem(buyer, itemID) != buyerQuantity + quantity) continue;
        if (!TakeNItems(chest, itemID, -quantity))
        {
            TakeNItems(buyer, itemID, -quantity);
            continue;
        }
        TraderStock_RecordPlayerSale(buyer, itemID, quantity);
        proceeds += salePrice * quantity;
    }
    if (proceeds > 0)
    {
        AddMoneyToCharacter(pchar, proceeds);
        Statistic_AddValue(pchar, "Money_get", proceeds);
        AddCharacterExpToSkill(pchar, "Commerce", proceeds / 1000.0);
        WaitDate("", 0, 0, 0, 0, 5);
    }
    return proceeds;
}

