// Native cannon models publish one damage entry per gun, without the legacy
// fcannon/cannonf alias ambiguity. At least one intact bort must be reloadable.
int Ship_GetCompanionAmmoMinimum(ref rCharacter)
{
	if (!CheckAttribute(rCharacter, "Ship.Cannons.Borts")) return 0;
	aref borts, bort, damages;
	makearef(borts, rCharacter.Ship.Cannons.Borts);
	int minimum = 0;
	for (int i = 0; i < GetAttributesNum(borts); i++)
	{
		bort = GetAttributeN(borts, i);
		if (!CheckAttribute(bort, "damages")) continue;
		makearef(damages, bort.damages);
		int intact = 0;
		for (int j = 0; j < GetAttributesNum(damages); j++)
		{
			if (stf(GetAttributeValue(GetAttributeN(damages, j))) < 1.0) intact++;
		}
		if (intact > 0 && (minimum == 0 || intact < minimum)) minimum = intact;
	}
	return minimum;
}

bool Ship_CompanionKeepCharge(ref rCharacter)
{
	// Cargo is consumed at load time, not at fire time. Keep a fallback reload
	// until native readiness or broadside fire, even with zero spare rounds.
	if (CheckAttribute(rCharacter, "Tmp.CompanionChargeReload"))
	{
		if (sti(rCharacter.Tmp.CompanionChargeReload) == sti(rCharacter.Ship.Cannons.Charge.Type) &&
			CheckAttribute(rCharacter, "BOAL_ReadyCharge") && rCharacter.BOAL_ReadyCharge == "1") return true;
		DeleteAttribute(rCharacter, "Tmp.CompanionChargeReload");
	}
	aref borts, bort, damages;
	makearef(borts, rCharacter.Ship.Cannons.Borts);
	for (int i = 0; i < GetAttributesNum(borts); i++)
	{
		bort = GetAttributeN(borts, i);
		if (!CheckAttribute(bort, "damages") || !CheckAttribute(bort, "ChargeRatio")) continue;
		if (stf(bort.ChargeRatio) <= 0.8) continue;
		makearef(damages, bort.damages);
		for (int j = 0; j < GetAttributesNum(damages); j++)
		{
			if (stf(GetAttributeValue(GetAttributeN(damages, j))) < 1.0) return true;
		}
	}
	return false;
}

int Ship_SelectCompanionCharge(ref rCharacter, float distance)
{
	int current = sti(rCharacter.Ship.Cannons.Charge.Type);
	int minimum = Ship_GetCompanionAmmoMinimum(rCharacter);
	if (minimum <= 0 || sti(rCharacter.Ship.Cannons.Type) == CANNON_TYPE_NONECANNON) return current;
	if (Ship_CompanionKeepCharge(rCharacter)) return current;
	// No ammunition substitution can supply missing powder.
	if (GetCargoGoods(rCharacter, GOOD_POWDER) < minimum) return current;
	bool balls = GetCargoGoods(rCharacter, GOOD_BALLS) >= minimum;
	bool bombs = GetCargoGoods(rCharacter, GOOD_BOMBS) >= minimum;
	bool knippels = GetCargoGoods(rCharacter, GOOD_KNIPPELS) >= minimum;
	bool grapes = GetCargoGoods(rCharacter, GOOD_GRAPES) >= minimum;
	int selected = current;
	if (CheckAttribute(rCharacter, "ShipCannonChargeType"))
	{
		selected = sti(rCharacter.ShipCannonChargeType);
		if (GetCargoGoods(rCharacter, selected) < minimum)
		{
			DeleteAttribute(rCharacter, "ShipCannonChargeType");
			selected = current;
		}
	}
	if (!CheckAttribute(rCharacter, "ShipCannonChargeType"))
	{
		if (GetCargoGoods(rCharacter, current) < minimum ||
			(CheckAttribute(rCharacter, "BOAL_ReadyCharge") && rCharacter.BOAL_ReadyCharge == "0"))
		{
			selected = Ship_FindOtherBallType(rCharacter, distance, balls, bombs, grapes, knippels);
			// Tactical range preferences must not strand the ship with dry guns.
			if (selected < 0)
			{
				if (bombs) selected = GOOD_BOMBS;
				else if (balls) selected = GOOD_BALLS;
				else if (knippels) selected = GOOD_KNIPPELS;
				else if (grapes) selected = GOOD_GRAPES;
			}
		}
		else
		{
			ref cannon = GetCannonByType(sti(rCharacter.Ship.Cannons.Type));
			float range = 550.0;
			if (CheckAttribute(cannon, "FireRange")) range = stf(cannon.FireRange);
			if (distance > range * 0.9 && balls) selected = GOOD_BALLS;
		}
	}
	if (selected >= 0)
	{
		if (selected != current)
		{
			Ship_ChangeCharge(rCharacter, selected);
			rCharacter.Tmp.CompanionChargeReload = selected;
		}
		rCharacter.BOAL_ReadyCharge = "1";
	}
	return selected;
}

